import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums for main items ---
  it("quotes an empty item list at 5 G (processing fee only)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("quotes a plain sword at 105 G (100 G base + 5 G fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 105 }] });
  });
  it("quotes a plain amulet at 65 G (60 G base + 5 G fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 65 }] });
  });
  it("quotes a plain staff at 85 G (80 G base + 5 G fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 85 }] });
  });
  it("quotes a plain potion at 45 G (40 G base + 5 G fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 45 }] });
  });

  // --- Components and the building block of 3 alike components ---
  it("quotes a single rune at 25 G base premium", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 30 }] });
  });
  it("quotes 2 runes at 50 G base premium", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 55 }] });
  });
  it("quotes 3 runes at 60 G base premium (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 65 }] });
  });
  it("quotes 4 runes at 100 G base premium (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 105 }] });
  });
  it("quotes 7 runes at 175 G base premium (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 180 }] });
  });
  it("quotes 2 runes + 1 moonstone at 75 G base premium (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 80 }] });
  });
  it("quotes 3 runes + 3 moonstones at 120 G base premium (two separate blocks)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array.from({ length: 3 }, () => ({ type: "rune" })),
            ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 125 }] });
  });

  // --- Item-specific premium modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium");
  it.todo("adds a 30 % surcharge for enchantment exactly 5");
  it.todo("adds no high-enchantment surcharge for enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo(
    "applies the curse surcharge only to the cursed item on a multi-item policy — cursed sword + plain amulet → 210 G before further modifiers and fee",
  );

  // --- Policy-wide premium modifiers ---
  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first insurance surcharge to every quote");
  it.todo("applies a 15 % follow-up discount to the customer's second quote");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favour)");
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favour)");

  // --- Integration examples for the premium ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) at 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");

  // --- Claim processing: standard reimbursement ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
  it.todo("pays out 100 G for a damaged rune with 200 G damage (no enchantment or material, so no special clause)");

  // --- Claim processing: special clauses ---
  it.todo("pays out 400 G for a steel sword with enchantment 9 and 1000 G damage (50 % clause, then deductible)");
  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 and 800 G damage (full reimbursement, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment 8 and 1000 G damage (50 % clause wins, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 and 1000 G damage (50 % clause wins, then deductible)");

  // --- Deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item — sword 500 G and amulet 300 G → payout 600 G");

  // --- Insurance sum and cap ---
  it.todo("reports the remaining cap after a claim — sword policy cap 2000 G, 500 G damage → payout 400 G, remaining cap 1600 G");
  it.todo("caps a policy of a sword and an amulet at 3200 G (insurance sum 1600 G)");
  it.todo("caps a cursed sword policy at 2000 G — premium modifiers do not raise the cap");
  it.todo("caps a policy of a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
  it.todo("exhausts the cap over successive claims — two 1500 G claims on a sword policy → payout 1400 G (cap 600 G left), then 600 G (cap 0 G left)");

  // --- Multiple items of the same type ---
  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");

  // --- Errors ---
  it.todo("rejects a quote containing an item with an unknown type");
  it.todo("rejects a claim whose damage entry references an item not covered by the policy");
  it.todo("rejects a claim whose damage entry has an unknown item type");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");
  it.todo("rejects a claim containing a damage entry with a negative amount");
});

