export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const ALIKE_ITEMS_PER_BLOCK = 3;
const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_RATE = 0.5;

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();

  for (const item of items) {
    const group = groups.get(item.type);
    if (group) group.push(item);
    else groups.set(item.type, [item]);
  }

  return [...groups.values()];
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === ALIKE_ITEMS_PER_BLOCK ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumOf));

const curseSurchargeOf = (item: Item): number =>
  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;

const quote = ({ items }: QuoteStep): StepResult => {
  const totalBasePremium = sum(groupByType(items).map(basePremiumOfGroup));
  const totalCurseSurcharge = sum(items.map(curseSurchargeOf));

  return { premium: totalBasePremium + totalCurseSurcharge + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: [quote(scenario.steps[0] as QuoteStep)],
});

