export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const ALIKE_ITEMS_PER_BLOCK = 3;
const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const groupByType = (items: Item[]): Item[][] => {
  const itemsByType = new Map<string, Item[]>();

  for (const item of items) {
    const alikeItems = itemsByType.get(item.type);
    if (alikeItems) alikeItems.push(item);
    else itemsByType.set(item.type, [item]);
  }

  return [...itemsByType.values()];
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];

const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
  alikeItems.length === ALIKE_ITEMS_PER_BLOCK
    ? BLOCK_BASE_PREMIUM
    : sum(alikeItems.map(basePremiumOf));

const curseSurchargeOf = (item: Item): number =>
  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;

const highEnchantmentSurchargeOf = (item: Item): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;

const surchargesOf = (item: Item): number =>
  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);

const loyaltyDiscountOf = (customer: Customer, basePremium: number): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? basePremium * LOYALTY_DISCOUNT_RATE : 0;

const quote = ({ items }: QuoteStep, customer: Customer): StepResult => {
  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
  const surcharges = sum(items.map(surchargesOf));
  const loyaltyDiscount = loyaltyDiscountOf(customer, basePremium);

  return {
    premium: basePremium + surcharges - loyaltyDiscount + PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: [quote(scenario.steps[0] as QuoteStep, scenario.customer)],
});

export interface Customer {
  yearsWithMHPCO: number;
}

