const followUpDiscountOf = (previousQuotes: number, basePremium: number): number =>
  previousQuotes > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;

const quote = (
  { items }: QuoteStep,
  customer: Customer,
  previousQuotes: number,
): StepResult => {
  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
  const itemSurcharges = sum(items.map(itemSurchargesOf));
  const loyaltyDiscount = loyaltyDiscountOf(customer, basePremium);
  const firstInsuranceSurcharge = firstInsuranceSurchargeOf(basePremium);
  const followUpDiscount = followUpDiscountOf(previousQuotes, basePremium);

  return {
    premium:
      basePremium +
      itemSurcharges -
      loyaltyDiscount +
      firstInsuranceSurcharge -
      followUpDiscount +
      PROCESSING_FEE,
  };
};

