const insuranceValueOf = (item: Item): number => INSURANCE_VALUE_BY_ITEM_TYPE[item.type];

const insuranceSumOf = (items: Item[]): number => sum(items.map(insuranceValueOf));

const claim = ({ incident }: ClaimStep, policyItems: Item[]): StepResult => {
  const payout = sum(
    incident.damages.map((damage) => damage.amount - DEDUCTIBLE_PER_DAMAGE),
  );
  const cap = insuranceSumOf(policyItems) * CAP_MULTIPLE;

  return { payout: Math.floor(payout), remainingCap: cap - payout };
};

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
  const policyItemsByStep = new Map<number, Item[]>();
  let quotesSoFar = 0;

  const results = steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      return claim(step, policyItemsByStep.get(step.policy) ?? []);
    }

    policyItemsByStep.set(stepIndex, step.items);
    const result = quote(step, customer, quotesSoFar > 0);
    quotesSoFar += 1;

    return result;
  });

  return { results };
};

