  remainingCap: number;
}

const claim = ({ incident }: ClaimStep, policy: Policy): StepResult => {
  const desiredPayout = sum(
    incident.damages.map((damage) => {
      const damagedItem = policy.items.find((item) => item.type === damage.itemType);

      return payoutForDamage(damage, damagedItem as Item);
    }),
  );
  const payout = Math.min(desiredPayout, policy.remainingCap);
  policy.remainingCap -= payout;

  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
};

